        getPerformanceSummary(history) {
            if (!history.length) return {};

            var lastState = history[history.length - 1];
            var ds = lastState.domainState || {};

            var comp = this._composite(ds);
            var onTimeRate = comp.onTimeRate;
            var totalCost = comp.totalCost;
            var costPerUnit = comp.costPerUnit;
            var throughputEff = comp.throughputEff;
            var fillRate = comp.fillRate;
            var totalScore = comp.score;

            var performanceKey = 'perf_disorder';
            if (totalScore >= 80) { performanceKey = 'perf_expert'; }
            else if (totalScore >= 65) { performanceKey = 'perf_competent'; }
            else if (totalScore >= 50) { performanceKey = 'perf_learning'; }
            var performanceLabel = this._t(performanceKey);

            var T = function(k) { return window.mySimulation.t(k); };
            var money = function(v) { return 'MXN $' + Math.round(v).toLocaleString('en-US'); };
            var insights = [];
            // the mistakes this run actually made, named first (EQIL G-M); never describe a play not made
            if (ds.firstProduct === 'work') insights.push(T('insight_biggest_first'));
            if (ds.orderD_declined) insights.push(T('insight_rush_declined'));
            else if ((ds.totalPenaltyCost || 0) > 0) insights.push(T('insight_rush_penalty'));
            else if (ds.orderD_accepted && !ds.orderD_delivered) insights.push(T('insight_rush_late'));
            if ((ds.totalOvertimeCost || 0) > 0) insights.push(T('insight_overtime').replace('{cost}', money(ds.totalOvertimeCost)));
            if ((ds.changeovers || 0) >= 3) insights.push(T('insight_many_changeovers'));
            if (onTimeRate >= 75) insights.push(T('insight_good_delivery'));
            if (onTimeRate < 50) insights.push(T('insight_poor_delivery'));
            if ((ds.changeovers || 0) <= 1) insights.push(T('insight_few_changeovers'));
            if (fillRate >= 0.95) insights.push(T('insight_good_throughput'));
            else if (fillRate < 0.8) insights.push(T('insight_low_throughput'));

            return {
                score: totalScore,
                overallScore: totalScore,
                totalScore: totalScore,
                onTimeRate: Math.round(onTimeRate),
                fillRate: Math.round(fillRate * 100),
                costPerUnit: Math.round(costPerUnit),
                throughputEfficiency: Math.round(throughputEff),
                performance: performanceKey.replace('perf_', ''),   // stable id; the display text is performanceLabel
                performanceLabel: performanceLabel,
                performanceKey: performanceKey,
                totalRevenue: ds.totalRevenue || 0,
                totalCost: totalCost,
                netProfit: (ds.totalRevenue || 0) - totalCost,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var day = state.currentPeriod;
            var ds = state.domainState;

            if (results.changeoverCost > 200) {
                return window.mySimulation.t('hint_changeover');
            }
            if (day === 2 && ds.orderB_remaining > 0 && state.decisions.product === 'work') {
                return window.mySimulation.t('hint_orderB_urgent');
            }
            if (day === 3 && ds.orderC_remaining > 0 && state.decisions.product === 'school') {
                return window.mySimulation.t('hint_orderC_urgent');
            }
            if (results.queueSewing > 200) {
                return window.mySimulation.t('hint_bottleneck_queue');
            }
            if (results.profit < 0) {
                return window.mySimulation.t('hint_loss');
            }
            return null;
        }

