        _updateBriefing(state) {
            var day = Math.min((state.currentPeriod || 1), 5);
            var briefKey = 'briefing_day' + day;
            var dayKey = 'dayname_' + day;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                var text = window.mySimulation ? window.mySimulation.t(briefKey) : '';
                briefEl.innerHTML = text || '';
            }

            var dayNameEl = document.getElementById('dayNameDisplay');
            if (dayNameEl) {
                var dayName = window.mySimulation ? window.mySimulation.t(dayKey) : '';
                dayNameEl.textContent = dayName || '';
            }

            // Show/hide rush panel
            var rushPanel = document.getElementById('rushPanel');
            if (rushPanel) {
                if (day === this.RUSH_DAY && state.domainState && !state.domainState.orderD_visible) {
                    rushPanel.style.display = 'block';
                } else {
                    rushPanel.style.display = 'none';
                }
            }

            // Update orders panel
            if (state.domainState) {
                this._updateOrdersPanel(state.domainState, day);
            }
        }

        // One scoring function for every period and the debrief (contract C1, gate G-D).
        // On time 35 (orders), cost per delivered unit 30, throughput 20 (Goldratt: units sold on time
        // over units ordered, not units made), sequencing 15 (fewer changeovers).
        _composite(ds) {
            var totalOrders = (ds.onTimeCount || 0) + (ds.lateCount || 0);
            var onTimeRate = totalOrders > 0 ? ((ds.onTimeCount || 0) / totalOrders) * 100 : 0;
            var totalCost = (ds.totalVariableCost || 0) + (ds.totalChangeoverCost || 0) + (ds.totalOvertimeCost || 0) + (ds.totalPenaltyCost || 0);
            var costPerUnit = totalCost / (ds.totalAllocated || 1);
            var throughputEff = ((ds.totalUnitsProduced || 0) / (75 * 8 * 5)) * 100;
            var fillRate = (ds.dueUnits || 0) > 0 ? (ds.onTimeUnits || 0) / ds.dueUnits : 0;
            var seqScore = Math.max(0, 1 - ((ds.changeovers || 0) / 4));
            var costRatio = Math.max(0, Math.min(1, 300 / Math.max(costPerUnit, 1)));
            var score = Math.max(0, Math.min(100, Math.round(35 * (onTimeRate / 100) + 30 * costRatio + 20 * fillRate + 15 * seqScore)));
            return { score: score, onTimeRate: onTimeRate, totalCost: totalCost, costPerUnit: costPerUnit, throughputEff: throughputEff, fillRate: fillRate };
        }

        _shipStock(ds, fam) {
            var key = fam === 'work' ? 'workStock' : 'schoolStock';
            var ids = fam === 'work' ? ['C', 'A'] : (ds.orderD_accepted ? ['D', 'B'] : ['B']);
            var shipped = 0;
            for (var i = 0; i < ids.length; i++) {
                var rk = 'order' + ids[i] + '_remaining';
                if (ds[rk] > 0 && ds[key] > 0) {
                    var q = Math.min(ds[key], ds[rk]);
                    ds[rk] -= q; ds[key] -= q; shipped += q;
                }
            }
            return shipped;
        }

        _updateOrdersPanel(ds, day) {
            var panel = document.getElementById('ordersPanel');
            if (!panel) return;

            var t = function(key) {
                return window.mySimulation ? window.mySimulation.t(key) : key;
            };

            var orders = [
                { id: 'A', type: 'work', total: 500, remaining: ds.orderA_remaining, due: 5, late: ds.orderA_late, delivered: ds.orderA_delivered },
                { id: 'B', type: 'school', total: 350, remaining: ds.orderB_remaining, due: 3, late: ds.orderB_late, delivered: ds.orderB_delivered },
                { id: 'C', type: 'work', total: 250, remaining: ds.orderC_remaining, due: 4, late: ds.orderC_late, delivered: ds.orderC_delivered }
            ];

            if (ds.orderD_visible) {
                orders.push({
                    id: 'D', type: 'school', total: 200,
                    remaining: ds.orderD_remaining, due: this.RUSH_DAY,
                    late: ds.orderD_late, delivered: ds.orderD_delivered,
                    accepted: ds.orderD_accepted, declined: ds.orderD_declined
                });
            }

            var dayNames = {
                1: t('dayname_1'), 2: t('dayname_2'), 3: t('dayname_3'),
                4: t('dayname_4'), 5: t('dayname_5')
            };

            var html = '<table class="table table-sm table-bordered">';
            html += '<thead class="thead-light"><tr>';
            html += '<th>' + t('order_id') + '</th>';
            html += '<th>' + t('order_product') + '</th>';
            html += '<th>' + t('order_quantity') + '</th>';
            html += '<th>' + t('order_due') + '</th>';
            html += '<th>' + t('order_remaining') + '</th>';
            html += '<th>' + t('order_status') + '</th>';
            html += '</tr></thead><tbody>';

            for (var i = 0; i < orders.length; i++) {
                var o = orders[i];
                var status = '';
                var badge = '';

                if (o.id === 'D' && o.declined) {
                    status = t('status_declined');
                    badge = 'badge-secondary';
                } else if (o.remaining <= 0 && (o.delivered || o.remaining === 0)) {
                    if (o.late) {
                        status = t('status_late');
                        badge = 'badge-danger';
                    } else {
                        status = t('status_completed');
                        badge = 'badge-success';
                    }
                } else if (o.late) {
                    status = t('status_late');
                    badge = 'badge-danger';
                } else if (o.remaining < o.total) {
                    status = t('status_inprogress');
                    badge = 'badge-warning';
                } else {
                    status = t('status_pending');
                    badge = 'badge-light';
                }

                var productIcon = o.type === 'work' ? '👔' : '🎒';
                var productLabel = o.type === 'work' ? t('product_work') : t('product_school');
                var pctDone = Math.round(((o.total - o.remaining) / o.total) * 100);

                html += '<tr>';
                html += '<td><strong>' + o.id + '</strong></td>';
                html += '<td>' + productIcon + ' ' + productLabel + '</td>';
                html += '<td>' + o.total + '</td>';
                html += '<td>' + (dayNames[o.due] || o.due) + '</td>';
                html += '<td>' + o.remaining + ' <small class="text-muted">(' + pctDone + '%)</small></td>';
                html += '<td><span class="badge ' + badge + '">' + status + '</span></td>';
                html += '</tr>';
            }

            html += '</tbody></table>';
            panel.innerHTML = html;
        }
    }

